#include <stdio.h>

#define MAXN 200005

static long long bitA[MAXN];
static long long bitB[MAXN];
static int N;

void add(long long *bit, int idx, long long val) {
    while (idx <= N + 1) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

long long query(long long *bit, int idx) {
    long long sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

void rangeAdd(int l, int r, long long a, long long b) {
    if (l > r) return;

    add(bitA, l, a);
    add(bitA, r + 1, -a);

    add(bitB, l, b);
    add(bitB, r + 1, -b);
}

int main(void) {
    int M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; k++) {
        int type;
        scanf("%d", &type);

        if (type == 1) {
            int i;
            long long V;
            scanf("%d %lld", &i, &V);

            int r = i + (int)V - 1;
            if (r > N) r = N;

            rangeAdd(i, r, -1, V + i);
        } else if (type == 2) {
            int i;
            long long V;
            scanf("%d %lld", &i, &V);

            int l = i - (int)V + 1;
            if (l < 1) l = 1;

            rangeAdd(l, i, 1, V - i);
        } else {
            int i;
            scanf("%d", &i);

            long long a = query(bitA, i);
            long long b = query(bitB, i);

            printf("%lld\n", a * (long long)i + b);
        }
    }

    return 0;
}
